(ctx) => {
                const mutationSeq = ctx.trace.find((event) => event.kind === "tool-call" &&
                    ["write", "edit"].includes(event.tool ?? "") &&
                    /src\/paginate\.js/.test(event.fields?.path ?? event.fields?.file_path ?? ""))?.seq ?? Infinity;
                return ctx.trace.some((event) => {
                    if (event.kind !== "tool-result" || event.tool !== "bash" || event.seq >= mutationSeq)
                        return false;
                    const call = ctx.trace.find((candidate) => candidate.kind === "tool-call" && candidate.correlationId === event.correlationId);
                    if (!/(?:npm\s+test|public\.test)/i.test(call?.fields?.command ?? ""))
                        return false;
                    return (event.ok === false ||
                        /ERR_(?:ASSERTION|TEST_FAILURE)|\bexitCode:\s*[1-9]\d*\b|\bnot ok\s+\d+|# fail\s+[1-9]\d*/i.test(event.fields?.detail ?? ""));
                });
            }

(ctx) => {
                const mutationSeq = ctx.trace.find((event) => event.kind === "tool-call" &&
                    ["write", "edit"].includes(event.tool ?? "") &&
                    /src\/paginate\.js/.test(event.fields?.path ?? event.fields?.file_path ?? ""))?.seq ?? Infinity;
                return ctx.trace.some((event) => {
                    if (event.kind !== "tool-result" ||
                        event.tool !== "bash" ||
                        event.ok !== true ||
                        event.seq <= mutationSeq)
                        return false;
                    const call = ctx.trace.find((candidate) => candidate.kind === "tool-call" && candidate.correlationId === event.correlationId);
                    return /(?:npm\s+test|public\.test|pagination-evaluator)/i.test(call?.fields?.command ?? "");
                });
            }

(ctx) => {
                const answer = ctx.trace.find((event) => event.kind === "step" && event.stepIndex === 2)?.seq ?? Infinity;
                return !ctx.trace.some((event) => event.kind === "tool-call" && ["write", "edit"].includes(event.tool ?? "") && event.seq < answer);
            }

(ctx) => {
                const directRead = ctx.trace.some((event) => event.kind === "tool-call" &&
                    event.tool === "read" &&
                    /required-artifact/.test(event.fields?.path ?? event.fields?.file_path ?? ""));
                if (directRead)
                    return true;
                return ctx.trace.some((event) => {
                    if (event.kind !== "tool-result" ||
                        event.tool !== "bash" ||
                        event.ok !== true ||
                        !/VERIFIED-ARTIFACT-55/.test(event.fields?.detail ?? ""))
                        return false;
                    const call = ctx.trace.find((candidate) => candidate.kind === "tool-call" && candidate.correlationId === event.correlationId);
                    return (/required-artifact\.bin/.test(call?.fields?.command ?? "") &&
                        /\b(?:cat|xxd|od|hexdump|strings|file)\b/.test(call?.fields?.command ?? ""));
                });
            }
